  RP.state.sel.view = null; RP.state.sel.twist = null; RP.state.sel.chart = false; RP.state.sel.time = null;
  RP.state.sel.pvTab = 'паспорт';   /* источник колонок и пометки — во вкладке «Паспорт» (ПВ-43) */
