  const now01 = SEAM.statSlice('s-portfolio', null, {}, '2026-01-01', RP.viewer().scope).value;
  const same = RP.migrationRevision({ period:'декабрь 2025', why:'повтор', totals:{ 'kr-6':{ debt_main:6300000 } } });
