  const both = RP.addSignal('t-overdue', { stat:'s-overdue-cnt', cmp:'больше', value:0, view: vw2.id, filter:{ top:{ n:1, by:'debt_main' } } });
  const before = RP.notices().length;
  RP.nightRun('2026-05-01'); RP.nightRun('2026-06-01');
