    bl('t-notice', 'user'); RP.state.view = 'registry'; RP.blankPrint('t-notice'); const d595 = RP.vbDialogs(), o595 = [...cutD(d595, '<select aria-label="объект печати"', '</select>').matchAll(/<option value="[^"]+"[^>]*>([^<]+)/g)].map(x => x[1]);
